208		if err := appendDeleteUserAttachments(ctx, tx, `
209			SELECT
210				id,
211				uid,
212				creator_id,
213				memo_id,
214				storage_type,
215				reference,
216				payload
217			FROM attachment
218			WHERE creator_id = `+deleteUserPlaceholder(1), []any{userID}, seen, &attachments); err != nil {
219			return nil, err
220		}
221	
222		for _, batch := range deleteUserBatches(memoIDs, deleteUserBatchSize) {
223			clause, args := deleteUserInClause(1, batch)
224			if err := appendDeleteUserAttachments(ctx, tx, `
225				SELECT
226					id,
227					uid,
228					creator_id,
229					memo_id,
230					storage_type,
231					reference,
232					payload
233				FROM attachment
234				WHERE memo_id IN `+clause, args, seen, &attachments); err != nil {
235				return nil, err
236			}
237		}
238	
239		return attachments, nil
240	}
