507	func deleteUserInClause[T any](start int, values []T) (string, []any) {
508		placeholders := make([]string, 0, len(values))
509		args := make([]any, 0, len(values))
510		for i, value := range values {
511			placeholders = append(placeholders, deleteUserPlaceholder(start+i))
512			args = append(args, value)
513		}
514		return "(" + strings.Join(placeholders, ", ") + ")", args
515	}
516	
517	func deleteUserBatches[T any](values []T, size int) [][]T {
518		if len(values) == 0 {
519			return nil
520		}
521		if size <= 0 {
522			size = len(values)
523		}
524	
525		batches := make([][]T, 0, (len(values)+size-1)/size)
526		for start := 0; start < len(values); start += size {
527			end := min(start+size, len(values))
528			batches = append(batches, values[start:end])
529		}
530		return batches
531	}
532	
533	func memoIDsFromRefs(memos []deleteUserMemoRef) []int32 {
534		ids := make([]int32, 0, len(memos))
535		for _, memo := range memos {
536			ids = append(ids, memo.ID)
537		}
538		return ids
539	}
