541	func memoIDSetFromRefs(memos []deleteUserMemoRef) map[int32]struct{} {
542		idSet := make(map[int32]struct{}, len(memos))
543		for _, memo := range memos {
544			idSet[memo.ID] = struct{}{}
545		}
546		return idSet
547	}
