549	func memoContentIDsFromRefs(memos []deleteUserMemoRef) []string {
550		contentIDs := make([]string, 0, len(memos))
551		for _, memo := range memos {
552			contentIDs = append(contentIDs, "memos/"+memo.UID)
553		}
554		return contentIDs
555	}
